DDL="""CREATE TABLE IF NOT EXISTS alliance_magazine_pixel_exams(
 exam_id TEXT PRIMARY KEY,
 version TEXT NOT NULL,
 student_version TEXT NOT NULL,
 page_manifest_sha256 TEXT NOT NULL,
 truth_manifest_sha256 TEXT NOT NULL,
 prediction_freeze_sha256 TEXT NOT NULL,
 frozen_at TIMESTAMPTZ NOT NULL,
 status TEXT NOT NULL,
 total_truth_listings INTEGER NOT NULL,
 matched_truth_listings INTEGER NOT NULL,
 recall NUMERIC(8,4) NOT NULL,
 page_results JSONB NOT NULL,
 result JSONB NOT NULL,
 created_at TIMESTAMPTZ DEFAULT NOW()
)"""

PROMPT="""You are the STUDENT vision extractor in a blind real-estate magazine pixel exam.
Read ONLY the supplied page image. Extract every atomic property inventory line from the central
classified listing body. Do not include magazine headers, page title, broker footer, contact banner,
agency advertisement, or generic service text as a property.
Return compact JSON exactly as:
{"listings":["raw listing 1","raw listing 2",...]}
Rules:
- one physical/listed inventory line per array item
- preserve block/property identifier, area, floor/configuration, price if printed, and phone/contact digits
- do not merge nearby lines
- do not invent unreadable text
- keep each item concise and close to printed wording
"""

def _engine(core): return getattr(core,"engine",None)
def _app(core): return getattr(core,"app",None) or core
def _client(core): return getattr(core,"client",None)
def _route_exists(app,path):
    try:return any(getattr(r,"path",None)==path for r in app.routes)
    except Exception:return False
def _sha_text(x):
    return hashlib.sha256(str(x).encode("utf-8")).hexdigest()
def _norm(s):
    s=str(s or "").upper()
    s=re.sub(r"[^A-Z0-9@.+/-]+"," ",s)
    return re.sub(r"\s+"," ",s).strip()
def _tokens(s):
    return set(re.findall(r"[A-Z0-9]+",_norm(s)))
def _phones(s):
    vals=[]
    for raw in re.findall(r"(?:\+?91[- ]?)?(?:\d[- ]?){8,13}",str(s or "")):
        d=re.sub(r"\D","",raw)
        if d.startswith("91") and len(d)==12:d=d[2:]
        if 8 <= len(d) <= 11: vals.append(d)
    return vals
def _anchor(s):
    n=_norm(s)
    m=re.match(r"([A-Z]+-?\d+[A-Z]?|[A-Z]+-BLOCK|S-BLK)",n)
    return m.group(1) if m else ""
def _sim(a,b):
    ta,tb=_tokens(a),_tokens(b)
    if not ta or not tb:return 0.0
    return len(ta&tb)/len(ta|tb)

def _match_truth(truth,preds):
    unused=set(range(len(preds)))
    matches=[]
    misses=[]
    for t in truth:
        ta=_anchor(t)
        tp=set(_phones(t))
        best_i=None;best_score=-1.0
        for i in unused:
            p=preds[i]
            pa=_anchor(p)
            pp=set(_phones(p))
            score=_sim(t,p)
            if ta and pa and ta==pa: score += 0.55
            if tp and pp and (tp & pp): score += 0.80
            if score>best_score:
                best_score=score;best_i=i
        # Require either a strong text match, or anchor+phone/context agreement.
        if best_i is not None and best_score>=0.62:
            matches.append({"truth":t,"prediction":preds[best_i],"score":round(best_score,4)})
            unused.remove(best_i)
        else:
            misses.append(t)
    extras=[preds[i] for i in sorted(unused)]
    return matches,misses,extras

def _extract_page(core,page_no,data):
    client=_client(core)
    if client is None:
        raise RuntimeError("GEMINI client unavailable")
    part=types.Part.from_bytes(data=data,mime_type="image/jpeg")
    resp=client.models.generate_content(
        model=os.getenv("GEMINI_MODEL","gemini-3.1-flash-lite"),
        contents=[PROMPT,part],
        config=types.GenerateContentConfig(
            response_mime_type="application/json",
            temperature=0.0,
            max_output_tokens=30000
        )
    )
    raw=(resp.text or "").strip()
    if raw.startswith("```"):
        raw=re.sub(r"^```(?:json)?\s*","",raw)
        raw=re.sub(r"\s*```$","",raw)
    data=json.loads(raw)
    listings=data.get("listings") or []
    return [str(x).strip() for x in listings if str(x).strip()]

def _install(engine):
    with engine.begin() as c:c.execute(text(DDL))
    # Add original source page pixels to the immutable evidence vault.
    for page_no,b64 in PAGE_IMAGES_B64.items():
        raw=base64.b64decode(b64)
        got=hashlib.sha256(raw).hexdigest()
        expected=PAGE_IMAGE_SHA256[str(page_no)] if str(page_no) in PAGE_IMAGE_SHA256 else PAGE_IMAGE_SHA256[page_no]
        if got!=expected:
            raise RuntimeError(f"Pixel hash mismatch page {page_no}")
        vault.capture_bytes(
            engine,
            None,
            raw,
            "MAGAZINE_FRESH_PIXEL_EXAM",
            f"DELHI_AUG_2026_PAGE_{page_no}.jpg",
            "image/jpeg",
            "CHATGPT_LIBRARY_ORIGINAL_PAGE_SEED"
        )

def _existing(engine):
    with engine.connect() as c:
        return c.execute(text("SELECT result FROM alliance_magazine_pixel_exams WHERE exam_id=:e"),{"e":EXAM_ID}).scalar()

def run_once(core):
    if not _LOCK.acquire(blocking=False):
        return {"status":"SKIPPED","reason":"PIXEL_EXAM_ALREADY_RUNNING"}
    try:
        engine=_engine(core)
        if engine is None:raise RuntimeError("Core engine unavailable")
        if student.VERSION!=EXPECTED_STUDENT:
            raise RuntimeError(f"Certified semantic student changed: {student.VERSION}")
        _install(engine)

        old=_existing(engine)
        if old:
            STATE["result"]=old
            STATE["status"]=old.get("status","FROZEN") if isinstance(old,dict) else "FROZEN"
            return old

        page_manifest=_sha_text(json.dumps(PAGE_IMAGE_SHA256,sort_keys=True))
        truth_manifest=_sha_text(json.dumps(TRUTH_LINES,sort_keys=True,ensure_ascii=False))
        frozen_at=datetime.now(timezone.utc)

        predictions={}
        for p in sorted(int(x) for x in PAGE_IMAGES_B64):
            raw=base64.b64decode(PAGE_IMAGES_B64[str(p)] if str(p) in PAGE_IMAGES_B64 else PAGE_IMAGES_B64[p])
            predictions[p]=_extract_page(core,p,raw)

        prediction_freeze=_sha_text(json.dumps(predictions,sort_keys=True,ensure_ascii=False))

        total_truth=0;total_match=0
        page_results=[]
        for p in sorted(predictions):
            truth=TRUTH_LINES[str(p)] if str(p) in TRUTH_LINES else TRUTH_LINES[p]
            pred=predictions[p]
            matches,misses,extras=_match_truth(truth,pred)
            total_truth+=len(truth);total_match+=len(matches)
            recall=round(100*len(matches)/max(len(truth),1),4)
            page_results.append({
                "page":p,
                "truth_count":len(truth),
                "student_count":len(pred),
                "matched":len(matches),
                "recall":recall,
                "misses":misses[:15],
                "extra_count":len(extras),
                "extras":extras[:15],
                "sample_matches":matches[:8]
            })

        recall=round(100*total_match/max(total_truth,1),4)

        # Pixel gate is intentionally demanding. We require >=98% recall overall,
        # every page >=97%, and no page may lose more than 2 true listings.
        per_page_ok=all(x["recall"]>=97.0 and (x["truth_count"]-x["matched"])<=2 for x in page_results)
        status="AUTOMATED_INDEPENDENT_MAGAZINE_PIXEL_PASS" if recall>=98.0 and per_page_ok else "AUTOMATED_INDEPENDENT_MAGAZINE_PIXEL_HOLD"

        result={
          "version":VERSION,
          "mode":MODE,
          "exam_id":EXAM_ID,
          "status":status,
          "student":{"semantic_version":student.VERSION,"frozen":True},
          "source":{
             "name":"DELHI AUG-26(2).pdf",
             "original_library_pages":[30,31,32],
             "original_page_count":110,
             "pixel_truth":True
          },
          "freeze":{
             "page_manifest_sha256":page_manifest,
             "truth_manifest_sha256":truth_manifest,
             "prediction_freeze_sha256":prediction_freeze,
             "frozen_at":frozen_at.isoformat(),
             "tuning_during_exam":False
          },
          "exam":{
             "pages":3,
             "total_truth_listings":total_truth,
             "matched_truth_listings":total_match,
             "recall":recall,
             "page_results":page_results,
             "pass_rule":"overall recall >=98%; each page >=97%; maximum 2 missed true listings per page"
          },
          "next_gate":"UNIFIED_MAGAZINE_PIXEL_TO_CANONICAL_SHADOW_PIPELINE" if status.endswith("_PASS") else "TRAIN_SEPARATE_VISION_CHALLENGER_ON_FROZEN_PIXEL_FAILURES",
          "safety":{
             "canonical_property_writes":0,"canonical_requirement_writes":0,"gold_mutations":0,
             "champion_mutations":0,"semantic_student_mutations":0,"production_writes":0,
             "pixel_evidence_additive_only":3
          }
        }

        with engine.begin() as c:
            c.execute(text("""INSERT INTO alliance_magazine_pixel_exams(
                exam_id,version,student_version,page_manifest_sha256,truth_manifest_sha256,
                prediction_freeze_sha256,frozen_at,status,total_truth_listings,matched_truth_listings,
                recall,page_results,result
            ) VALUES(:e,:v,:sv,:pm,:tm,:pf,:fa,:st,:tt,:mt,:r,CAST(:pr AS JSONB),CAST(:res AS JSONB))"""),
            {"e":EXAM_ID,"v":VERSION,"sv":student.VERSION,"pm":page_manifest,"tm":truth_manifest,
             "pf":prediction_freeze,"fa":frozen_at,"st":status,"tt":total_truth,"mt":total_match,
             "r":recall,"pr":json.dumps(page_results,ensure_ascii=False),"res":json.dumps(result,ensure_ascii=False)})

        STATE["result"]=result;STATE["status"]=status;STATE["last_error"]=None
        return result
    except Exception as exc:
        STATE["status"]="ERROR";STATE["last_error"]=f"{type(exc).__name__}: {exc}"
        return {"version":VERSION,"exam_id":EXAM_ID,"status":"ERROR","error":STATE["last_error"]}
    finally:
        _LOCK.release()

def status(core):
    return STATE["result"] or run_once(core)

def dashboard(core):
    s=status(core);e=s.get("exam") or {}
    return f"""<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>
<title>Magazine Pixel Certification 5.7</title><style>
body{{font-family:Arial;background:#f5f7fb;color:#172033;margin:0}}header{{background:#102235;color:#fff;padding:18px}}
.wrap{{max-width:1300px;margin:auto;padding:18px}}.card{{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:14px;margin-bottom:12px}}
pre{{white-space:pre-wrap;background:#0f172a;color:#e2e8f0;padding:14px;border-radius:10px;overflow:auto}}</style></head>
<body><header><b>Alliance Magazine Fresh Pixel Certification 5.7</b><br><small>Original magazine pages · immutable truth manifest · frozen vision extraction</small></header>
<div class='wrap'><div class='card'><b>{html.escape(str(s.get("status")))}</b><br>
Recall {html.escape(str(e.get("recall")))}% · Matched {html.escape(str(e.get("matched_truth_listings")))} / {html.escape(str(e.get("total_truth_listings")))}</div>
<pre>{html.escape(json.dumps(s,ensure_ascii=False,indent=2))}</pre></div></body></html>"""

def register(core):
    app=_app(core)
    if not _route_exists(app,"/api/property-brain/magazine-pixel-v570/status"):
        @app.get("/api/property-brain/magazine-pixel-v570/status")
        def _status():return status(core)
    if not _route_exists(app,"/property-brain/magazine-pixel-v570"):
        @app.get("/property-brain/magazine-pixel-v570",response_class=HTMLResponse)
        def _page():return HTMLResponse(dashboard(core))
    return {"status":"REGISTERED","version":VERSION,"route":"/property-brain/magazine-pixel-v570"}

def _runner(core):
    time.sleep(int(os.getenv("ALLIANCE_MAGAZINE_PIXEL_EXAM_DELAY","60")))
    run_once(core)

def start(core):
    global _STARTED
    register(core)
    if _STARTED:return STATE
    _STARTED=True
    threading.Thread(target=_runner,args=(core,),name="magazine-pixel-v570",daemon=True).start()
    return STATE
